from pathlib import Path
import datetime, hashlib, json, subprocess, sys
base=Path(sys.argv[1]).resolve(); baseline=Path(sys.argv[2]).resolve(); out=base/'decoded-comparison'
assert not out.exists();out.mkdir()
def read(p):return json.loads(Path(p).read_text())
def sha(p):
 h=hashlib.sha256()
 with Path(p).open('rb') as f:
  for block in iter(lambda:f.read(1024*1024),b''):h.update(block)
 return h.hexdigest()
def decode(file, name, frames):
 print('Decoding '+name,flush=True)
 video=out/(name+'.framemd5');audio=out/(name+'.audio.sha256')
 with video.open('wb')as f:subprocess.run(['ffmpeg','-v','error','-threads:v','1','-i',str(file),'-map','0:v:0','-an','-pix_fmt','yuv420p','-fps_mode','passthrough','-enc_time_base:v','1:90000','-threads:v','1','-f','framemd5','-'],stdout=f,check=True,timeout=900)
 with audio.open('wb')as f:subprocess.run(['ffmpeg','-v','error','-i',str(file),'-map','0:a:0','-vn','-c:a','pcm_f32le','-f','hash','-'],stdout=f,check=True,timeout=900)
 rows=[x.strip()for x in video.read_text().splitlines()if x and not x.startswith('#')];assert len(rows)==frames
 return rows,audio.read_text().strip(),{'videoHashFile':str(video),'videoHashFileSHA256':sha(video),'audioHashFile':str(audio),'audioHashFileSHA256':sha(audio)}
r=read(base/'results.json');old=read(baseline/'results.json');assert r['status'] in ['completed','failed']
report={'date':datetime.datetime.now(datetime.timezone.utc).isoformat(),'status':'running','scope':'All decoded yuv420p frames including PTS and frame durations, and the whole decoded float32 PCM. Identical compressed file pairs are decoded once with every actual file hash rechecked. Synthetic composition only; no general perceptual-quality claim.','sourceSHA256':sha(__file__),'comparisons':[],'runs':[]}
seen={}
for run in r['runs']:
 prev=next(x for x in old['runs']if x['surface']==run['surface']and x['inputSeconds']==run['inputSeconds'])
 assert sha(run['outputFile'])==run['outputSHA256'] and sha(prev['outputFile'])==prev['outputSHA256']
 pair=(run['outputSHA256'],prev['outputSHA256'])
 if pair not in seen:
  index=len(seen);frames=read(base/run['verificationFile'])['frames']['frames']
  before,audio_before,files_before=decode(prev['outputFile'],f'{index}-baseline',frames)
  after,audio_after,files_after=decode(run['outputFile'],f'{index}-candidate',frames)
  compared={'index':index,'baselineOutputSHA256':pair[1],'candidateOutputSHA256':pair[0],'frames':frames,'differingFrames':sum(x!=y for x,y in zip(before,after)),'wholeVideoRowsEqual':before==after,'wholeFloatAudioEqual':audio_before==audio_after,'decodedAudioHash':audio_after,'baselineFiles':files_before,'candidateFiles':files_after}
  report['comparisons'].append(compared);seen[pair]=index
  (out/'results.json').write_text(json.dumps(report,indent=2)+'\n')
  assert compared['wholeVideoRowsEqual'] and compared['wholeFloatAudioEqual'],compared
 report['runs'].append({'surface':run['surface'],'seconds':run['inputSeconds'],'iteration':run['iteration'],'comparisonIndex':seen[pair],'actualFileHashVerified':True})
report['status']='completed';(out/'results.json').write_text(json.dumps(report,indent=2)+'\n')
(out/'executed.py').write_bytes(Path(__file__).read_bytes())
print(json.dumps({'status':report['status'],'comparisons':[{k:c[k]for k in ['frames','differingFrames','wholeVideoRowsEqual','wholeFloatAudioEqual']}for c in report['comparisons']],'runs':len(report['runs'])}))
